import React, { useMemo, useState } from "react";
import axios from "axios";
import ReactMarkdown from "react-markdown";
import "./App.css";

function parseUnifiedDiff(diffText) {
  if (!diffText) return { type: "empty", rows: [], message: "" };
  const trimmed = String(diffText).trim();
  if (!trimmed) return { type: "empty", rows: [], message: "" };
  if (trimmed.toLowerCase().includes("not enough versions")) {
    return { type: "message", rows: [], message: trimmed };
  }

  const lines = trimmed.split(/\r?\n/);
  const rows = [];

  let oldLn = 0;
  let newLn = 0;
  let pendingDel = null; // { oldLn, text }

  const flushPendingDel = () => {
    if (!pendingDel) return;
    rows.push({
      kind: "del",
      old: { ln: pendingDel.oldLn, text: pendingDel.text },
      next: { ln: null, text: "" }
    });
    pendingDel = null;
  };

  for (const line of lines) {
    if (line.startsWith("---") || line.startsWith("+++")) continue;
    if (line.startsWith("@@")) {
      flushPendingDel();
      const m = /@@\s*-(\d+)(?:,\d+)?\s+\+(\d+)(?:,\d+)?\s*@@/.exec(line);
      if (m) {
        oldLn = Number(m[1]);
        newLn = Number(m[2]);
      }
      continue;
    }

    if (line.startsWith("\\ No newline at end of file")) continue;

    const tag = line[0];
    const text = line.slice(1);

    if (tag === " ") {
      flushPendingDel();
      rows.push({
        kind: "ctx",
        old: { ln: oldLn || null, text },
        next: { ln: newLn || null, text }
      });
      oldLn += 1;
      newLn += 1;
      continue;
    }

    if (tag === "-") {
      flushPendingDel();
      pendingDel = { oldLn: oldLn || null, text };
      oldLn += 1;
      continue;
    }

    if (tag === "+") {
      if (pendingDel) {
        rows.push({
          kind: "change",
          old: { ln: pendingDel.oldLn, text: pendingDel.text },
          next: { ln: newLn || null, text }
        });
        pendingDel = null;
      } else {
        rows.push({
          kind: "add",
          old: { ln: null, text: "" },
          next: { ln: newLn || null, text }
        });
      }
      newLn += 1;
      continue;
    }
  }

  flushPendingDel();
  return { type: "diff", rows, message: "" };
}

function CompareView({ diffText }) {
  const parsed = useMemo(() => parseUnifiedDiff(diffText), [diffText]);
  const [showAll, setShowAll] = useState(false);

  if (parsed.type === "message") {
    return (
      <div className="pp-alert pp-alertInfo">
        <p className="pp-alertTitle">Nothing to compare yet</p>
        <p className="pp-alertBody">{parsed.message}</p>
      </div>
    );
  }

  if (parsed.type !== "diff" || parsed.rows.length === 0) {
    return null;
  }

  const rows = parsed.rows;
  const unchanged = rows.filter((r) => r.kind === "ctx").length;
  const changed = rows.length - unchanged;

  // Show only context around changes unless expanded.
  const contextRadius = 2;
  const visible = showAll
    ? rows.map((r, idx) => ({ r, idx, hidden: false }))
    : rows.map((r, idx) => {
        if (r.kind !== "ctx") return { r, idx, hidden: false };
        // keep context lines within radius of a change
        for (let j = Math.max(0, idx - contextRadius); j <= Math.min(rows.length - 1, idx + contextRadius); j++) {
          if (rows[j].kind !== "ctx") return { r, idx, hidden: false };
        }
        return { r, idx, hidden: true };
      });

  const hiddenCount = visible.reduce((acc, x) => acc + (x.hidden ? 1 : 0), 0);

  const rendered = [];
  let i = 0;
  while (i < visible.length) {
    if (!visible[i].hidden) {
      rendered.push(visible[i]);
      i += 1;
      continue;
    }
    // collapse a run of hidden lines
    let j = i;
    while (j < visible.length && visible[j].hidden) j += 1;
    rendered.push({ collapsed: true, count: j - i, key: `c-${i}-${j}` });
    i = j;
  }

  return (
    <div className="pp-compare">
      <div className="pp-compareHeader">
        <div>Previous</div>
        <div>Latest</div>
      </div>

      <div className="pp-cardBody" style={{ padding: "12px 12px 10px" }}>
        <div className="pp-kv" style={{ marginTop: 0 }}>
          <span><strong>Changed</strong> {changed} lines</span>
          <span><strong>Unchanged</strong> {unchanged} lines</span>
          {hiddenCount > 0 && (
            <span><strong>Hidden</strong> {hiddenCount} lines</span>
          )}
        </div>
      </div>

      <div className="pp-compareRows">
        {rendered.map((item) => {
          if (item.collapsed) {
            return (
              <div className="pp-collapse" key={item.key}>
                <button className="pp-linkBtn" onClick={() => setShowAll(true)}>
                  Show {item.count} unchanged line{item.count === 1 ? "" : "s"}
                </button>
              </div>
            );
          }

          const row = item.r;
          const rowClass =
            row.kind === "add" ? "pp-row pp-rowAdd" :
            row.kind === "del" ? "pp-row pp-rowDel" :
            row.kind === "change" ? "pp-row pp-rowChange" :
            "pp-row pp-rowCtx";

          return (
            <div className={rowClass} key={item.idx}>
              <div className="pp-cell">
                <div className="pp-ln">{row.old.ln ?? ""}</div>
                <div className="pp-code">{row.old.text}</div>
              </div>
              <div className="pp-cell">
                <div className="pp-ln">{row.next.ln ?? ""}</div>
                <div className="pp-code">{row.next.text}</div>
              </div>
            </div>
          );
        })}
      </div>

      {!showAll && hiddenCount > 0 && (
        <div className="pp-collapse">
          <button className="pp-linkBtn" onClick={() => setShowAll(true)}>
            Show full comparison
          </button>
        </div>
      )}
    </div>
  );
}

function AuthScreen({ onAuth }) {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const apiBaseUrl = "http://127.0.0.1:8000";

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (email && password) {
      setError("");
      setLoading(true);
      try {
        if (isLogin) {
          const params = new URLSearchParams();
          params.append("username", email);
          params.append("password", password);
          const res = await axios.post(`${apiBaseUrl}/login`, params);
          onAuth(res.data.access_token);
        } else {
          const res = await axios.post(`${apiBaseUrl}/signup`, { name, email, password });
          if (res.data.access_token) {
            onAuth(res.data.access_token);
          }
        }
      } catch (e) {
        setError(e?.response?.data?.detail || "Authentication failed");
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div className="pp-page pp-authPage">
      <div className="pp-shell pp-authShell">
        <header className="pp-header" style={{ justifyContent: "center", marginBottom: "32px", textAlign: "center" }}>
          <div>
            <h1 className="pp-title" style={{ fontSize: "36px" }}>PropelPro AI</h1>
            <p className="pp-subtitle" style={{ margin: "12px auto 0" }}>
              Intelligent Sales Proposal Architect
            </p>
          </div>
        </header>

        <div className="pp-card pp-authCard">
          <div className="pp-cardHeader">
            <h2 className="pp-cardTitle">{isLogin ? "Welcome Back" : "Create Account"}</h2>
          </div>
          <div className="pp-cardBody">
            {error && (
              <div className="pp-alert pp-alertError" role="alert" style={{ marginBottom: "16px" }}>
                <p className="pp-alertBody">{error}</p>
              </div>
            )}
            <form className="pp-form" onSubmit={handleSubmit}>
              {!isLogin && (
                <div className="pp-field">
                  <label htmlFor="name">Name</label>
                  <input
                    id="name"
                    className="pp-input"
                    placeholder="Enter your name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    required
                  />
                </div>
              )}
              <div className="pp-field">
                <label htmlFor="email">Email</label>
                <input
                  id="email"
                  type="email"
                  className="pp-input"
                  placeholder="Enter your email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </div>
              <div className="pp-field">
                <label htmlFor="password">Password</label>
                <input
                  id="password"
                  type="password"
                  className="pp-input"
                  placeholder="Enter your password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </div>
              <div className="pp-actions" style={{ gridTemplateColumns: '1fr', marginTop: '14px' }}>
                <button type="submit" className="pp-btn pp-btnPrimary" style={{ fontSize: '15px', padding: '12px' }} disabled={loading}>
                  {loading ? (
                    <>
                      <span className="pp-spinner" />
                      Please wait…
                    </>
                  ) : isLogin ? "Login" : "Sign Up"}
                </button>
              </div>
            </form>
            <div style={{ textAlign: "center", marginTop: "16px", fontSize: "14px" }}>
              <button
                className="pp-linkBtn"
                onClick={() => setIsLogin(!isLogin)}
                style={{ background: "none", border: "none", color: "var(--accent)" }}
              >
                {isLogin ? "Don't have an account? Sign up" : "Already have an account? Login"}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [token, setToken] = useState("");

  const handleAuth = (access_token) => {
    setToken(access_token);
    setIsAuthenticated(true);
    axios.defaults.headers.common["Authorization"] = `Bearer ${access_token}`;
  };

  const [form, setForm] = useState({
    client: "",
    industry: "",
    budget: "",
    services: ""
  });

  const [result, setResult] = useState(null);
  const [diff, setDiff] = useState("");
  const [diffSummary, setDiffSummary] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const apiBaseUrl = useMemo(() => "http://127.0.0.1:8000", []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const generateProposal = async () => {
    setError("");
    setLoading(true);
    setDiff("");
    setDiffSummary("");
    try {
      const res = await axios.post(`${apiBaseUrl}/generate`, form);
      setResult(res.data);
    } catch (e) {
      const message =
        e?.response?.data?.detail ||
        e?.message ||
        "Request failed";
      setError(String(message));
    } finally {
      setLoading(false);
    }
  };

  const compareVersions = async () => {
    setError("");
    setLoading(true);
    try {
      const res = await axios.get(
        `${apiBaseUrl}/compare/${form.client}`
      );
      setDiff(res.data.diff);
      setDiffSummary(res.data.summary || "");
    } catch (e) {
      const message =
        e?.response?.data?.detail ||
        e?.message ||
        "Request failed";
      setError(String(message));
    } finally {
      setLoading(false);
    }
  };

  if (!isAuthenticated) {
    return <AuthScreen onAuth={handleAuth} />;
  }

  return (
    <div className="pp-page">
      <div className="pp-shell">
        <header className="pp-header">
          <div>
            <h1 className="pp-title">PropelPro AI</h1>
            <p className="pp-subtitle">
              Generate a client-ready proposal, an executive summary, and key risks.
              Compare versions anytime.
            </p>
          </div>
          <div className="pp-pillrow">
            <div className="pp-pill">Frontend: React</div>
            <div className="pp-pill">Backend: FastAPI</div>
            <div className="pp-pill">LLM: Ollama</div>
          </div>
        </header>

        <main className="pp-grid">
          <section className="pp-card">
            <div className="pp-cardHeader">
              <h2 className="pp-cardTitle">Project details</h2>
            </div>
            <div className="pp-cardBody">
              <div className="pp-form">
                <div className="pp-field">
                  <label htmlFor="client">Client</label>
                  <input
                    id="client"
                    name="client"
                    className="pp-input"
                    placeholder="e.g., Stark Trek"
                    value={form.client}
                    onChange={handleChange}
                  />
                </div>

                <div className="pp-field">
                  <label htmlFor="industry">Industry</label>
                  <input
                    id="industry"
                    name="industry"
                    className="pp-input"
                    placeholder="e.g., SaaS / Technology"
                    value={form.industry}
                    onChange={handleChange}
                  />
                </div>

                <div className="pp-field">
                  <label htmlFor="budget">Budget</label>
                  <input
                    id="budget"
                    name="budget"
                    className="pp-input"
                    placeholder="e.g., $150,000"
                    value={form.budget}
                    onChange={handleChange}
                  />
                </div>

                <div className="pp-field">
                  <label htmlFor="services">Services</label>
                  <textarea
                    id="services"
                    name="services"
                    className="pp-textarea"
                    placeholder="Migration, CI/CD, training, support…"
                    value={form.services}
                    onChange={handleChange}
                  />
                </div>

                <div className="pp-actions">
                  <button
                    className="pp-btn pp-btnPrimary"
                    onClick={generateProposal}
                    disabled={loading}
                  >
                    {loading ? (
                      <>
                        <span className="pp-spinner" />
                        Generating…
                      </>
                    ) : (
                      "Generate proposal"
                    )}
                  </button>
                  <button
                    className="pp-btn pp-btnSecondary"
                    onClick={compareVersions}
                    disabled={loading || !form.client}
                    title={!form.client ? "Enter a client name first" : undefined}
                  >
                    Compare versions
                  </button>
                </div>

                <p className="pp-hint">
                  Tip: first generation on a fresh Ollama model can take longer; subsequent runs are faster.
                </p>
              </div>
            </div>
          </section>

          <section className="pp-stack">
            {error && (
              <div className="pp-alert pp-alertError" role="alert">
                <p className="pp-alertTitle">Request failed</p>
                <p className="pp-alertBody">{error}</p>
              </div>
            )}

            {!result && !diff && !error && (
              <div className="pp-alert pp-alertInfo">
                <p className="pp-alertTitle">Ready when you are</p>
                <p className="pp-alertBody">
                  Fill in the project details and generate a proposal. You can compare past versions by client name.
                </p>
                <div className="pp-kv">
                  <span><strong>API</strong> {apiBaseUrl}</span>
                  <span><strong>Docs</strong> {apiBaseUrl}/docs</span>
                </div>
              </div>
            )}

            {result && (
              <div className="pp-card">
                <div className="pp-cardHeader">
                  <h2 className="pp-cardTitle">Proposal</h2>
                </div>
                <div className="pp-cardBody">
                  <div className="pp-markdown">
                    <ReactMarkdown>{result.proposal}</ReactMarkdown>
                  </div>
                </div>
              </div>
            )}

            {result?.summary && (
              <div className="pp-card">
                <div className="pp-cardHeader">
                  <h2 className="pp-cardTitle">Executive summary</h2>
                </div>
                <div className="pp-cardBody">
                  <div className="pp-markdown">
                    <ReactMarkdown>{result.summary}</ReactMarkdown>
                  </div>
                </div>
              </div>
            )}

            {result?.risks && (
              <div className="pp-card">
                <div className="pp-cardHeader">
                  <h2 className="pp-cardTitle">Risks & assumptions</h2>
                </div>
                <div className="pp-cardBody">
                  <div className="pp-markdown">
                    <ReactMarkdown>{result.risks}</ReactMarkdown>
                  </div>
                </div>
              </div>
            )}

            {diffSummary && (
              <div className="pp-card">
                <div className="pp-cardHeader">
                  <h2 className="pp-cardTitle">Changes in this Version</h2>
                </div>
                <div className="pp-cardBody">
                  <div className="pp-markdown">
                    <ReactMarkdown>{diffSummary}</ReactMarkdown>
                  </div>
                </div>
              </div>
            )}

            {diff && (
              <div className="pp-card">
                <div className="pp-cardHeader">
                  <h2 className="pp-cardTitle">Version comparison (Line by Line)</h2>
                </div>
                <div className="pp-cardBody">
                  <CompareView diffText={diff} />
                </div>
              </div>
            )}
          </section>
        </main>
      </div>
    </div>
  );
}

export default App;
